import{describe,it,expect}from"vitest";import{fortStyles,FEATURES,renderColumn}from"../../frontend/fort-architecture/fort-architecture.js";describe("Indian Fort Architecture Comparison Explorer",()=>{it("contains all 4 architectural styles (Rajput, Mughal, Maratha, European)",()=>{expect(fortStyles).toBeDefined(),expect(fortStyles.rajput).toBeDefined(),expect(fortStyles.mughal).toBeDefined(),expect(fortStyles.maratha).toBeDefined(),expect(fortStyles.european).toBeDefined()}),it("has complete metadata for each style",()=>{Object.values(fortStyles).forEach(e=>{expect(e.id).toBeDefined(),expect(e.name).toBeDefined(),expect(e.era).toBeDefined(),expect(e.defenseStrategy).toBeDefined(),expect(e.materials).toBeDefined(),expect(e.artisticStyle).toBeDefined(),expect(e.waterSystems).toBeDefined(),expect(Array.isArray(e.highlights)).toBe(!0),expect(Array.isArray(e.landmarks)).toBe(!0)})}),it("defines comparison features list",()=>{expect(Array.isArray(FEATURES)).toBe(!0),expect(FEATURES.length).toBeGreaterThanOrEqual(5)}),it("renders comparison column without throwing error",()=>{expect(()=>renderColumn("rajput")).not.toThrow();const e=renderColumn("rajput");expect(e).toContain("Rajput Forts")})});